// UpdateNewValues updates the mutable fields using the new values that
// were set on create. Using this option is equivalent to using:
//
//	client.TestcaseRevision.Create().
//		OnConflict(
//			sql.ResolveWithNewValues(),
//			sql.ResolveWith(func(u *sql.UpdateSet) {
//				u.SetIgnore(testcaserevision.FieldID)
//			}),
//		).
//		Exec(ctx)
func (u *TestcaseRevisionUpsertBulk) UpdateNewValues() *TestcaseRevisionUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithNewValues())
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(s *sql.UpdateSet) {
		for _, b := range u.create.builders {
			if _, exists := b.mutation.ID(); exists {
				s.SetIgnore(testcaserevision.FieldID)
			}
			if _, exists := b.mutation.CreatedAt(); exists {
				s.SetIgnore(testcaserevision.FieldCreatedAt)
			}
			if _, exists := b.mutation.TestCaseID(); exists {
				s.SetIgnore(testcaserevision.FieldTestCaseID)
			}
			if _, exists := b.mutation.ProblemID(); exists {
				s.SetIgnore(testcaserevision.FieldProblemID)
			}
			if _, exists := b.mutation.TestsetRevisionID(); exists {
				s.SetIgnore(testcaserevision.FieldTestsetRevisionID)
			}
			if _, exists := b.mutation.GroupID(); exists {
				s.SetIgnore(testcaserevision.FieldGroupID)
			}
			if _, exists := b.mutation.Kind(); exists {
				s.SetIgnore(testcaserevision.FieldKind)
			}
			if _, exists := b.mutation.GroupIndex(); exists {
				s.SetIgnore(testcaserevision.FieldGroupIndex)
			}
			if _, exists := b.mutation.OrderIndex(); exists {
				s.SetIgnore(testcaserevision.FieldOrderIndex)
			}
			if _, exists := b.mutation.InputAssetID(); exists {
				s.SetIgnore(testcaserevision.FieldInputAssetID)
			}
			if _, exists := b.mutation.ExpectedAssetID(); exists {
				s.SetIgnore(testcaserevision.FieldExpectedAssetID)
			}
			if _, exists := b.mutation.Weight(); exists {
				s.SetIgnore(testcaserevision.FieldWeight)
			}
			if _, exists := b.mutation.StopOnFailure(); exists {
				s.SetIgnore(testcaserevision.FieldStopOnFailure)
			}
		}
	}))
	return u
}

